# Logger Config
logger = logging.getLogger(__name__)

# Environment Variables
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = int(os.getenv("SMTP_PORT", 465))
SMTP_USER = os.getenv("SMTP_USER")
SMTP_PASSWORD = os.getenv("SMTP_PASSWORD")
ADMIN_EMAIL = os.getenv("ADMIN_EMAIL", "office@affordablehome-ac.com")

async def verify_connection():
    if not HAS_SMTP:
        logger.error("❌ SMTP Verification Skipped: 'aiosmtplib' is missing.")
        return

    try:
        logger.info(f"🔌 Testing SMTP Connection to {SMTP_SERVER}:{SMTP_PORT}...")
        async with aiosmtplib.SMTP(hostname=SMTP_SERVER, port=SMTP_PORT, use_tls=True) as smtp:
            await smtp.login(SMTP_USER, SMTP_PASSWORD)
            logger.info("✅ SMTP Connection Verified.")
    except Exception as e:
        logger.error(f"❌ SMTP Connection FAILED: {e}")

# Helper to load logo
def get_logo_attachment():
    try:
        # Attempt to find logo in standard locations
        paths = [
            "apps/web/public/logo-new.png",
            "../web/public/logo-new.png",
            "/app/apps/web/public/logo-new.png", # Docker container path
            "logo-new.png"
        ]
        
        for p in paths:
            if os.path.exists(p):
                with open(p, 'rb') as f:
                    img_data = f.read()
                    image = MIMEImage(img_data)
                    image.add_header('Content-ID', '<logo_paramount>')
                    image.add_header('Content-Disposition', 'inline', filename='logo.png')
                    return image
        
        return None
    except Exception as e:
        logger.error(f"Error loading logo: {e}")
        return None

LOGO_B64 = ""
